'use client'

import { cn, useDraggable, useSignal, useSignals } from '@cascivo/core'
import type { ReactNode, Ref } from 'react'
import styles from './swipe-item.module.css'

/** Width (px) of one revealed action. Must match `.action { inline-size }` in the CSS. */
const ACTION_WIDTH = 72
/** How far ahead (ms) release velocity is projected when deciding the snap target. */
const PROJECT_MS = 100

export interface SwipeAction {
  /** Stable React key. Provide when `label` may repeat across actions. */
  id?: string
  /** Accessible name and visible label. */
  label: string
  icon?: ReactNode
  onSelect: () => void
  /** Render in the destructive (danger) style. */
  destructive?: boolean
}

export interface SwipeItemProps {
  /** The row content. */
  children: ReactNode
  /**
   * Actions revealed by dragging toward the end edge (shown on the start edge)
   *
   * @defaultValue `[]`
   * @see the component manifest
   */
  leadingActions?: SwipeAction[]
  /**
   * Actions revealed by dragging toward the start edge (shown on the end edge)
   *
   * @defaultValue `[]`
   * @see the component manifest
   */
  trailingActions?: SwipeAction[]
  className?: string
}

type OpenState = 'closed' | 'leading' | 'trailing'

/**
 * A list row whose leading/trailing actions are revealed by a horizontal drag, snapping
 * open or closed on release (projected by fling velocity). The action buttons are always
 * in the DOM and the a11y tree — never gesture-only — and focusing one (keyboard) reveals
 * its side, so the row is fully operable without a pointer. Escape closes it. The drag is
 * physical-axis (tuned for LTR); CSS translate only, no animation library.
 */
export function SwipeItem({
  children,
  leadingActions = [],
  trailingActions = [],
  className,
}: SwipeItemProps) {
  useSignals()
  const committed = useSignal(0)
  const open = useSignal<OpenState>('closed')
  const leadW = leadingActions.length * ACTION_WIDTH
  const trailW = trailingActions.length * ACTION_WIDTH

  const { handleRef, offset, velocity, isDragging, reset } = useDraggable({
    axis: 'x',
    onDragEnd: (o) => {
      const vx = velocity.value.x
      const released = committed.value + o.x
      reset()
      const projected = released + vx * PROJECT_MS
      let target = 0
      if (leadW > 0 && projected > leadW / 2) target = leadW
      else if (trailW > 0 && projected < -trailW / 2) target = -trailW
      committed.value = target
      open.value = target > 0 ? 'leading' : target < 0 ? 'trailing' : 'closed'
    },
  })

  const reveal = (side: 'leading' | 'trailing'): void => {
    committed.value = side === 'leading' ? leadW : -trailW
    open.value = side
  }
  const close = (): void => {
    committed.value = 0
    open.value = 'closed'
    reset()
  }
  const select = (action: SwipeAction): void => {
    action.onSelect()
    close()
  }

  // Live translate: committed position plus the in-progress drag delta, clamped to the
  // revealable widths so the row can't be dragged past its actions.
  const x = Math.max(-trailW, Math.min(leadW, committed.value + offset.value.x))

  const renderPanel = (side: 'leading' | 'trailing', actions: SwipeAction[]): ReactNode => (
    <div className={cn(styles['panel'], styles[side])}>
      {actions.map((action, i) => (
        <button
          key={action.id ?? `${i}-${action.label}`}
          type="button"
          data-destructive={action.destructive ? '' : undefined}
          className={styles['action']}
          onFocus={() => reveal(side)}
          onClick={() => select(action)}
        >
          {action.icon && (
            <span className={styles['actionIcon']} aria-hidden="true">
              {action.icon}
            </span>
          )}
          <span className={styles['actionLabel']}>{action.label}</span>
        </button>
      ))}
    </div>
  )

  return (
    <div
      className={cn(styles['root'], className)}
      data-state={open.value}
      onKeyDown={(event) => {
        if (event.key === 'Escape' && open.value !== 'closed') close()
      }}
    >
      {leadingActions.length > 0 && renderPanel('leading', leadingActions)}
      {trailingActions.length > 0 && renderPanel('trailing', trailingActions)}
      <div
        ref={handleRef as Ref<HTMLDivElement>}
        className={styles['content']}
        data-dragging={isDragging.value ? '' : undefined}
        style={{ transform: `translateX(${x}px)` }}
      >
        {children}
      </div>
    </div>
  )
}

@layer cascivo.component {
  .root {
    position: relative;
    overflow: hidden;
    background: var(--cascivo-color-surface);
  }

  .panel {
    position: absolute;
    inset-block: 0;
    display: flex;
  }

  .leading {
    inset-inline-start: 0;
  }

  .trailing {
    inset-inline-end: 0;
  }

  .content {
    position: relative;
    display: flex;
    align-items: center;
    min-block-size: var(--cascivo-target-min-coarse, 2.75rem);
    background: var(--cascivo-color-surface);
    /* Vertical scrolling stays with the page; horizontal is the swipe gesture. */
    touch-action: pan-y;
    transition: transform var(--cascivo-motion-enter);

    &[data-dragging] {
      transition: none;
    }
  }

  .action {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: var(--cascivo-space-1);
    inline-size: 4.5rem; /* keep in sync with ACTION_WIDTH in swipe-item.tsx */
    padding-inline: var(--cascivo-space-2);
    font-size: var(--cascivo-text-xs);
    color: var(--cascivo-color-accent-content);
    background: var(--cascivo-color-accent);
    border: none;
    cursor: pointer;

    &:focus-visible {
      outline: none;
      box-shadow: var(--cascivo-focus-ring);
      /* Raise the focus ring above the sliding content. */
      z-index: 1;
    }

    &[data-destructive] {
      color: var(--cascivo-color-text-on-destructive);
      background: var(--cascivo-color-destructive);
    }
  }

  .actionIcon {
    display: inline-flex;
    inline-size: 1.25rem;
    block-size: 1.25rem;
  }

  .actionLabel {
    white-space: nowrap;
  }

  @media (prefers-reduced-motion: reduce) {
    .content {
      transition: none;
    }
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'SwipeItem',
  description:
    'List row whose leading/trailing actions are revealed by a horizontal swipe, with keyboard parity',
  category: 'display',
  // Actions are revealed by a horizontal swipe gesture and are unreachable otherwise.
  clientJs: 'required',
  states: ['closed', 'leading', 'trailing'],
  variants: [],
  sizes: [],
  props: [
    { name: 'children', type: 'React.ReactNode', required: true, description: 'The row content' },
    {
      name: 'leadingActions',
      default: '[]',
      type: 'SwipeAction[]',
      required: false,
      description: 'Actions revealed by dragging toward the end edge (shown on the start edge)',
    },
    {
      name: 'trailingActions',
      default: '[]',
      type: 'SwipeAction[]',
      required: false,
      description: 'Actions revealed by dragging toward the start edge (shown on the end edge)',
    },
    {
      name: 'className',
      description: 'Additional CSS class names merged onto the root element.',
      type: 'string',
      required: false,
    },
  ],
  tokens: [
    '--cascivo-color-surface',
    '--cascivo-color-accent',
    '--cascivo-color-accent-content',
    '--cascivo-color-destructive',
    '--cascivo-color-text-on-destructive',
    '--cascivo-target-min-coarse',
    '--cascivo-motion-enter',
  ],
  accessibility: {
    role: 'group',
    wcag: '2.2-AA',
    keyboard: ['Tab', 'Enter', 'Space', 'Escape'],
  },
  examples: [
    {
      title: 'Trailing actions',
      code: `<SwipeItem
  trailingActions={[
    { label: 'Archive', onSelect: archive },
    { label: 'Delete', onSelect: remove, destructive: true },
  ]}
>
  <MessageRow message={message} />
</SwipeItem>`,
    },
    {
      title: 'Leading and trailing',
      code: `<SwipeItem
  leadingActions={[{ label: 'Pin', icon: <PinIcon />, onSelect: pin }]}
  trailingActions={[{ label: 'Delete', onSelect: remove, destructive: true }]}
>
  <TaskRow task={task} />
</SwipeItem>`,
    },
  ],
  dependencies: ['@cascivo/core'],
  tags: ['display', 'swipe', 'list', 'mobile', 'gesture', 'actions'],
  intent: {
    whenToUse: [
      'List rows on touch surfaces where secondary actions (archive, delete) should hide until swiped',
      'Mail/inbox-style rows that reveal contextual actions behind the content',
      'Compact lists where always-visible action buttons would crowd each row',
    ],
    whenNotToUse: [
      'A single primary action per row — render it inline as a Button',
      'Destructive actions that need confirmation — pair with an AlertDialog instead of swipe-only',
      'Non-list, free-form content — swipe-to-reveal is a list-row affordance',
    ],
    antiPatterns: [
      {
        bad: 'Relying on the swipe gesture as the only way to reach Delete',
        good: 'Action buttons stay in the DOM and a11y tree; focusing one reveals its side',
        why: 'Gesture-only actions are unreachable by keyboard and screen-reader users',
      },
    ],
    related: [
      {
        name: 'ActionSheet',
        relationship: 'alternative',
        reason: 'Use an ActionSheet when a row tap should present a fuller list of actions',
      },
      {
        name: 'List',
        relationship: 'contained-by',
        reason: 'SwipeItem wraps individual rows within a list',
      },
    ],
    a11yRationale:
      'The action buttons are always rendered in the DOM and the accessibility tree, never gesture-only. Focusing an action (via keyboard) reveals its side so it is visible, Enter/Space activate it, and Escape closes the row — giving full keyboard and screen-reader parity with the swipe gesture. The drag uses touch-action: pan-y so vertical scrolling is unaffected.',
    flexibility: [
      {
        area: 'actions',
        level: 'flexible',
        note: 'Any number of leading and/or trailing actions; each may be destructive',
      },
      {
        area: 'reveal direction',
        level: 'strict',
        note: 'Leading reveals on the start edge, trailing on the end edge (physical-axis drag)',
      },
    ],
  },
}
